/**
 * The inclusion-proof verifier, cross-pinned two ways.
 *
 * First against fixtures generated by the normative implementation itself.
 * The `RUST_*` constants below are real proofs emitted by
 * `cargo run -p edet-state --example proof_fixture` over five founding
 * underwriters, captured in the node's wire shape — REGENERATE them from that
 * example rather than editing them by hand. They were once hand-copied, and
 * when `Section::ALL` grew a `pending` section under both sides this test kept
 * passing: the reimplementation and its oracle had drifted together, which is
 * the one failure a cross-pin exists to be immune to.
 *
 * Second against a prover written independently in this file: the verifier
 * derives each fold's structure from `(index, leaf_count)` and the
 * section's fixed position, so building trees here and mutating one field
 * at a time checks that every deviation from the committed shape — not
 * just a wrong hash — is rejected.
 */
import { afterEach, describe, expect, it, vi } from 'vitest';
import { sha256 } from '@noble/hashes/sha2';

import { parseProof, verifyProof, verifyProofJson, SECTIONS } from '../proof';
import { fetchProof } from '../api';
import { bytesToHex } from '../crypto';

// ------------------------------------------------- an independent prover ----

const SECTION_NAMES = ['members', 'contracts', 'proposals', 'validators', 'stakes', 'replay', 'ledger'];
// Kept as its own map, not derived from the order above: position and tag do
// not agree, and a prover that derived one from the other would model the
// verifier's own mistake instead of checking it. Mirrors `SECTION_TAG` in
// ../proof.
const SECTION_TAGS: Record<string, number> = {
    members: 0,
    contracts: 1,
    proposals: 2,
    validators: 3,
    stakes: 5,
    replay: 6,
    ledger: 4,
};

function enc(s: string): Uint8Array {
    return new TextEncoder().encode(s);
}

function cat(...parts: Uint8Array[]): Uint8Array {
    const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
    let at = 0;
    for (const p of parts) {
        out.set(p, at);
        at += p.length;
    }
    return out;
}

function be64(n: number): Uint8Array {
    const out = new Uint8Array(8);
    new DataView(out.buffer).setBigUint64(0, BigInt(n));
    return out;
}

/** `leaf_hash` per `root.rs`: 0x00 ‖ "edet-leaf-v3" ‖ salt ‖ tag ‖ be64(index) ‖ framed key ‖ framed value. */
function leaf(salt: Uint8Array, tag: number, index: number, key: Uint8Array, value: Uint8Array): Uint8Array {
    return sha256(
        cat(
            Uint8Array.of(0x00),
            enc('edet-leaf-v3'),
            salt,
            Uint8Array.of(tag),
            be64(index),
            be64(key.length),
            key,
            be64(value.length),
            value,
        ),
    );
}

function inner(l: Uint8Array, r: Uint8Array): Uint8Array {
    return sha256(cat(Uint8Array.of(0x01), l, r));
}

/**
 * `section_hash` per `root.rs`: 0x02 ‖ "edet-section-v1" ‖ tag ‖ be64(count)
 * ‖ leaves root. The section's leaf count is bound here and nowhere else, so
 * a prover that skipped it would agree with a verifier that skipped it too.
 */
function sectionRoot(tag: number, count: number, leavesRoot: Uint8Array): Uint8Array {
    return sha256(cat(Uint8Array.of(0x02), enc('edet-section-v1'), Uint8Array.of(tag), be64(count), leavesRoot));
}

/**
 * Build a promotion tree level by level — the prover-side shape, mirroring
 * `fold_level` in `root.rs` rather than the verifier's `fold_path`, so the
 * two sides arrive at the structure independently. Collects the sibling
 * consumed at each level by the node tracked from leaf `track`; a promoted
 * node contributes none.
 */
function merkle(leaves: Uint8Array[], track: number): { root: Uint8Array; path: Uint8Array[] } {
    let level = leaves.slice();
    let t = track;
    const path: Uint8Array[] = [];
    while (level.length > 1) {
        const up: Uint8Array[] = [];
        for (let i = 0; 2 * i < level.length; i++) {
            const l = level[2 * i];
            if (2 * i + 1 < level.length) {
                const r = level[2 * i + 1];
                up.push(inner(l, r));
                if (t === 2 * i) {
                    path.push(r);
                    t = -i - 1; // mark resolved for this level
                } else if (t === 2 * i + 1) {
                    path.push(l);
                    t = -i - 1;
                }
            } else {
                up.push(l); // odd level: the last node is promoted
                if (t === 2 * i) {
                    t = -i - 1;
                }
            }
        }
        level = up;
        t = -t - 1;
    }
    return { root: level[0], path };
}

/** The wire shape the node serves. */
interface Wire {
    section: string;
    index: number;
    leaf_count: number;
    key: string;
    value: string;
    leaf_salt: string;
    path: string[];
    section_path: string[];
}

/**
 * An honest fixture: a section of `leafCount` distinct leaves, the other six
 * section roots arbitrary (the verifier never inspects them), the top tree
 * folded over all seven in the fixed order. Salts are arbitrary 32-byte
 * values — the verifier recomputes the leaf from whatever salt the proof
 * disclosed, so any salt the tree was actually built with is honest.
 */
function fixture(section: string, leafCount: number, index: number, key?: Uint8Array): { root: string; proof: Wire } {
    // Position in the top tree and tag byte inside the leaf are two different
    // numbers, and this prover has to model both or it stops being independent
    // of the thing it checks.
    const pos = SECTION_NAMES.indexOf(section);
    const tag = SECTION_TAGS[section];
    const keys: Uint8Array[] = [];
    const values: Uint8Array[] = [];
    const salts: Uint8Array[] = [];
    const leaves: Uint8Array[] = [];
    for (let i = 0; i < leafCount; i++) {
        keys.push(key !== undefined && i === index ? key : be64(i));
        values.push(sha256(enc(`value-${section}-${i}`)));
        salts.push(sha256(enc(`salt-${section}-${i}`)));
        leaves.push(leaf(salts[i], tag, i, keys[i], values[i]));
    }
    const section_tree = merkle(leaves, index);
    const sectionRoots = SECTION_NAMES.map((name, i) =>
        i === pos ? sectionRoot(tag, leafCount, section_tree.root) : sha256(enc(`other-root-${name}`)),
    );
    const top = merkle(sectionRoots, pos);
    return {
        root: bytesToHex(top.root),
        proof: {
            section,
            index,
            leaf_count: leafCount,
            key: bytesToHex(keys[index]),
            value: bytesToHex(values[index]),
            leaf_salt: bytesToHex(salts[index]),
            path: section_tree.path.map(bytesToHex),
            section_path: top.path.map(bytesToHex),
        },
    };
}

